sys_script_include.script:
var infoTravelUtils = Class.create();
infoTravelUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    weatherDetails: function(cityName) {

        //var city = cityName ? cityName : this.getParameter('syscity');
        var city = cityName ? cityName.trim() : (this.getParameter('syscity') || '').trim();
        var temp_C;
        var temp_R;

        try {
            var r = new sn_ws.RESTMessageV2('x_2166443_info_t_0.getWeatherDetails', 'WeatherDetails');
            //r.setStringParameterNoEscape('location', city);
            r.setStringParameter('location', city);
			r.setStringParameterNoEscape('key', 'b912559c7d1d4155b9842251231701');


            var response = r.execute();
            var responseBody = response.getBody();
            // gs.info(responseBody);
            var httpStatus = response.getStatusCode();

            if (httpStatus == 200) {
                gs.info('Weather Response: ' + responseBody);

                var newObj = JSON.parse(responseBody);

                temp_C = newObj.current.temp_c;
                temp_R = newObj.current.chance_of_rain;
            }

        } catch (ex) {
            var message = ex.message;
        }


        var res = ` the current temp for ${city} is ${temp_C}C and chances of Rain is ${temp_R}%`;
        return res;
    },

    type: 'infoTravelUtils'
});
